/**
 * 선물 뭐하지? (Gift Recommendation Service)
 * 러블리 파스텔 미니멀 & 착한 소비 SDGs 연계 선물 추천 웹앱
 */

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => { initApp(); });
} else {
  initApp();
}

/* ------------------------------------------------------------
   1. 상태 관리 (State Management)
   ------------------------------------------------------------ */
const state = {
  soundEnabled: true,
  currentView: 'intro', // 'intro' | 'input' | 'result'
  form: {
    recipient: '',
    recipientCustom: '',
    gender: '',
    age: '',
    budget: '',
    budgetCustom: null,
    situation: '',
    situationCustom: ''
  },
  recommendedGifts: [], // [Slot1, Slot2, Slot3]
  recommendationIndex: 0 // 순환 추천 인덱스
};

/* ------------------------------------------------------------
   2. 효과음 합성 (Web Audio API Synthesizer)
   ------------------------------------------------------------ */
let audioCtx = null;
function getAudioContext() {
  if (!audioCtx) {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (AudioContext) audioCtx = new AudioContext();
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
  return audioCtx;
}

function playSound(type) {
  if (!state.soundEnabled) return;
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;

    if (type === 'pop') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(450, now);
      osc.frequency.exponentialRampToValueAtTime(800, now + 0.08);
      gain.gain.setValueAtTime(0.25, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.08);
    } else if (type === 'chime') {
      const freqs = [523.25, 659.25, 783.99, 1046.50];
      freqs.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, now + idx * 0.07);
        gain.gain.setValueAtTime(0.18, now + idx * 0.07);
        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.07 + 0.35);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + idx * 0.07);
        osc.stop(now + idx * 0.07 + 0.35);
      });
    } else if (type === 'celebrate') {
      const notes = [440, 554.37, 659.25, 880, 1108.73];
      notes.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, now + idx * 0.06);
        gain.gain.setValueAtTime(0.15, now + idx * 0.06);
        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.06 + 0.4);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + idx * 0.06);
        osc.stop(now + idx * 0.06 + 0.4);
      });
    }
  } catch (e) {
    console.warn('Audio play failed:', e);
  }
}

/* ------------------------------------------------------------
   3. 화면 전환 (View Routing)
   ------------------------------------------------------------ */
window.showView = showView;
function showView(viewName) {
  state.currentView = viewName;
  const views = document.querySelectorAll('.screen-view');
  views.forEach(v => {
    v.classList.remove('active');
  });

  const target = document.getElementById(`view-${viewName}`);
  if (target) {
    target.classList.add('active');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // 화면 전환 시 효과음
  if (viewName === 'input') {
    playSound('pop');
  }
}

/* ------------------------------------------------------------
   4. 토스트 알림 (Toast Notification)
   ------------------------------------------------------------ */
function showToast(message) {
  let toast = document.getElementById('app-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'app-toast';
    toast.className = 'app-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 2200);
}

/* ------------------------------------------------------------
   5. 입력 폼 제어 및 유효성 검사
   ------------------------------------------------------------ */
function updateBlockAnsweredStatus(groupName, isAnswered) {
  const block = document.getElementById(`block-${groupName}`);
  if (block) {
    if (isAnswered) {
      block.classList.add('is-answered');
    } else {
      block.classList.remove('is-answered');
    }
  }
}

function checkFormValidity() {
  const f = state.form;
  const isRecipientValid = !!f.recipient && (f.recipient !== 'custom' || (f.recipientCustom && f.recipientCustom.trim().length > 0));
  const isGenderValid = !!f.gender;
  const isAgeValid = !!f.age;
  const isBudgetValid = !!f.budget && (f.budget !== 'custom' || (f.budgetCustom !== null && f.budgetCustom > 0));
  const isSituationValid = !!f.situation && (f.situation !== 'custom' || (f.situationCustom && f.situationCustom.trim().length > 0));

  updateBlockAnsweredStatus('recipient', isRecipientValid);
  updateBlockAnsweredStatus('gender', isGenderValid);
  updateBlockAnsweredStatus('age', isAgeValid);
  updateBlockAnsweredStatus('budget', isBudgetValid);
  updateBlockAnsweredStatus('situation', isSituationValid);

  // 진행률 바 업데이트
  const progressFill = document.getElementById('formProgressFill');
  if (progressFill) {
    let answeredCount = 0;
    if (isRecipientValid) answeredCount++;
    if (isGenderValid) answeredCount++;
    if (isAgeValid) answeredCount++;
    if (isBudgetValid) answeredCount++;
    if (isSituationValid) answeredCount++;
    progressFill.style.width = `${(answeredCount / 5) * 100}%`;
  }

  const submitBtn = document.getElementById('submitFormBtn') || document.getElementById('submitBtn');
  const isAllValid = isRecipientValid && isGenderValid && isAgeValid && isBudgetValid && isSituationValid;
  if (submitBtn) {
    submitBtn.disabled = !isAllValid;
    if (isAllValid) {
      submitBtn.classList.add('ready-to-submit');
    } else {
      submitBtn.classList.remove('ready-to-submit');
    }
  }
  return isAllValid;
}

/* ------------------------------------------------------------
   6. 맞춤 선물 추천 엔진 (성별, 연령대, 예산 기반 정밀 매칭)
   * 엑셀 원본 데이터 100% 반영
   * 선물받을 사람과 상황은 화면 상단 태그 표시에만 사용
   ------------------------------------------------------------ */
function normalizeBudgetTier(budget, budgetCustom) {
  if (budget === 'custom' && budgetCustom != null) {
    const val = Number(budgetCustom);
    if (val < 10000) return '1만원 미만';
    if (val < 30000) return '1~3만원';
    if (val < 50000) return '3~5만원';
    if (val < 100000) return '5~10만원';
    return '10만원 이상';
  }
  if (budget) {
    if (budget.includes('10만원')) return '10만원 이상';
    return budget;
  }
  return '1~3만원';
}

function generateSmartRecommendations() {
  const f = state.form;
  const targetGender = f.gender || '여성';
  const targetAge = f.age || '20대';
  const targetBudget = normalizeBudgetTier(f.budget, f.budgetCustom);

  const slot1Pool = (window.SLOT1_DATA || []).filter(item => 
    item.gender === targetGender && item.age === targetAge && item.budget === targetBudget
  );

  const slot2Pool = (window.SLOT2_DATA || []).filter(item => 
    item.gender === targetGender && item.age === targetAge && item.budget === targetBudget
  );

  const slot3Pool = (window.SLOT3_DATA || []).filter(item => 
    item.gender === targetGender && item.age === targetAge && item.budget === targetBudget
  );

  const idx = state.recommendationIndex;

  // 1번 선물 매칭 (없을 경우 예산 매칭 -> 첫 상품 -> 기본 안전 객체)
  let gift1 = slot1Pool.length > 0 ? slot1Pool[idx % slot1Pool.length] : null;
  if (!gift1) {
    const fallback1 = (window.SLOT1_DATA || []).filter(item => item.gender === targetGender && item.budget === targetBudget);
    gift1 = fallback1.length > 0 ? fallback1[idx % fallback1.length] : null;
  }
  if (!gift1) {
    const fallbackBudget = (window.SLOT1_DATA || []).filter(item => item.budget === targetBudget);
    gift1 = fallbackBudget.length > 0 ? fallbackBudget[idx % fallbackBudget.length] : (window.SLOT1_DATA || [])[0];
  }
  if (!gift1) {
    gift1 = {
      name: "스타벅스 카페 아메리카노 T 2잔 + 부드러운 생크림 카스텔라",
      price: 14600,
      url: "https://gift.kakao.com",
      producer: "스타벅스",
      reason: "호불호 없는 인기템! 누구나 기분 좋게 즐길 수 있는 실패 없는 선물이에요 ☕"
    };
  }

  // 2번 선물 매칭 (없을 경우 예산 매칭 -> 첫 상품 -> 기본 안전 객체)
  let gift2 = slot2Pool.length > 0 ? slot2Pool[idx % slot2Pool.length] : null;
  if (!gift2) {
    const fallback2 = (window.SLOT2_DATA || []).filter(item => item.gender === targetGender && item.budget === targetBudget);
    gift2 = fallback2.length > 0 ? fallback2[idx % fallback2.length] : null;
  }
  if (!gift2) {
    const fallbackBudget2 = (window.SLOT2_DATA || []).filter(item => item.budget === targetBudget);
    gift2 = fallbackBudget2.length > 0 ? fallbackBudget2[idx % fallbackBudget2.length] : (window.SLOT2_DATA || [])[0];
  }
  if (!gift2) {
    gift2 = {
      name: "[록시땅] 시어 버터 핸드 크림 75ml",
      price: 29000,
      url: "https://gift.kakao.com",
      producer: "록시땅",
      reason: "내 돈 주고 사긴 아깝고 선물 받으면 매일 쓰며 감동하는 센스 만점 선물이에요 🌸"
    };
  }

  // 3번 선물 매칭 (해당 조건 3번 상품이 없는 경우에만 null 처리하여 스토어365 특별 카드 노출)
  const gift3 = slot3Pool.length > 0 ? slot3Pool[idx % slot3Pool.length] : null;

  state.recommendedGifts = [gift1, gift2, gift3];
  renderResultScreen();
}

