// 긴 상품명을 핵심 상품명과 상세 구성으로 분리
function splitProductName(fullName) {
  if (!fullName) return { mainName: '', subSpec: '' };
  let str = fullName.trim();

  // 대괄호 [브랜드명] 분리
  let bracketPart = '';
  const bracketMatch = str.match(/^(\[[^\]]+\])\s*(.*)$/);
  if (bracketMatch) {
    bracketPart = bracketMatch[1];
    str = bracketMatch[2].trim();
  }

  // 플러스(+)나 괄호(()) 또는 쉼표 기준으로 상세 구성 분리
  let mainName = str;
  let subSpec = '';

  const plusIdx = str.indexOf('+');
  if (plusIdx > 0) {
    mainName = str.substring(0, plusIdx).trim();
    subSpec = str.substring(plusIdx).trim();
  } else {
    const parenMatch = str.match(/^(.*?)(\(.*?\))$/);
    if (parenMatch && parenMatch[1].trim().length >= 4) {
      mainName = parenMatch[1].trim();
      subSpec = parenMatch[2].trim();
    }
  }

  if (bracketPart) {
    mainName = `${bracketPart} ${mainName}`;
  }

  return { mainName, subSpec };
}

