/* ------------------------------------------------------------
   8-1. 상품 맞춤 구매욕구 자극 추천 이유 생성기
   ------------------------------------------------------------ */
function getCompellingReason(p, targetGender) {
  if (!p || !p.name) return "소중한 사람에게 전하는 센스 만점 감동 선물이에요 💗";
  const n = (p.name || '').toLowerCase();
  const isFemale = targetGender === '여성';

  // 1. 물주머니, 찜질기, 파쉬, 핫팩 (유저 지정 문구 완벽 반영)
  if (n.includes('물주머니') || n.includes('찜질기') || n.includes('파쉬') || n.includes('핫팩')) {
    return isFemale 
      ? "여자는 배가 따뜻해야해요! 마법에 걸린 날 필수템 💕 쌀쌀한 날 품에 안고 있으면 사르르 녹아내리는 힐링 꿀템이에요"
      : "추운 날과 뻐근한 일상에 따뜻한 온기를 선물하는 필수템! 품에 안고 있으면 묵은 피로가 사르르 풀려요 🔥";
  }

  // 2. 커피, 아메리카노, 스타벅스, 투썸, 컴포즈, 메가커피
  if (n.includes('커피') || n.includes('아메리카노') || n.includes('스타벅스') || n.includes('투썸')) {
    return "출근길·점심 후 피로를 싹 날려주는 마법의 충전템! 매일 마시는 커피라 호불호 없이 누구나 가장 반기는 실패 없는 선물 ☕";
  }

  // 3. 디저트, 케이크, 카스텔라, 롤케익, 타르트
  if (n.includes('케이크') || n.includes('카스텔라') || n.includes('롤케익') || n.includes('타르트')) {
    return "기분 울적한 날 한 입 베어물면 당 충전 200%! 달콤하고 부드러운 행복을 전하는 센스 만점 디저트예요 🍰";
  }

  // 4. 아이스크림, 배스킨, 하겐다즈
  if (n.includes('아이스크림') || n.includes('배스킨') || n.includes('하겐다즈')) {
    return "냉동실에 쟁여두고 기분 전환할 때 꺼내먹는 힐링 간식! 남녀노소 누구나 좋아하는 달콤하고 시원한 선물 🍨";
  }

  // 5. 상품권, 기프트카드, 올리브영, 신세계, 백화점
  if (n.includes('올리브영') || n.includes('기프트카드') || n.includes('상품권') || n.includes('교환권')) {
    return "원하는 선물을 내 취향대로 직접 고르는 자유! 실패 확률 0%, 받는 순간 미소 짓게 되는 만족도 200% 만능 선물 🛍️";
  }

  // 6. 핸드크림 (록시땅, 논픽션, 탬버린즈, 이솝, 헤트라스 등)
  if (n.includes('핸드크림') || n.includes('핸드 크림')) {
    return "내 돈 주고 사긴 살짝 아깝지만 선물 받으면 매일 가방 속에 쏙 넣고 다니며 자랑하고픈 감성 보습템 🌸";
  }

  // 7. 립밤, 틴트, 립스틱
  if (n.includes('립밤') || n.includes('틴트') || n.includes('립스틱')) {
    return "건조한 입술에 맑고 생기 있는 촉촉함을 더해주는 파우치 필수템! 바를 때마다 선물한 사람을 떠올리게 돼요 💄";
  }

  // 8. 향수, 퍼퓸, 미스트
  if (n.includes('향수') || n.includes('퍼퓸') || n.includes('미스트')) {
    return "하루 종일 은은하게 기분 좋은 여운을 남겨주는 향기! 뿌리는 순간 일상이 특별해지는 감성 선물 💐";
  }

  // 9. 디퓨저, 캔들, 향초
  if (n.includes('디퓨저') || n.includes('캔들') || n.includes('향초')) {
    return "방 안 가득 은은한 향기로 가득 채워주는 인테리어 무드템! 집에 들어서는 순간 하루의 피로가 싹 풀려요 🕯️";
  }

  // 10. 비타민, 오쏘몰, 영양제
  if (n.includes('비타민') || n.includes('오쏘몰') || n.includes('영양제') || n.includes('유산균')) {
    return "야근과 일상에 지친 몸에 활력을 팍팍 불어넣는 프리미엄 충전제! 내 건강을 진심으로 챙겨주는 마음에 찐 감동해요 ⚡";
  }

  // 11. 홍삼, 인삼, 건강즙
  if (n.includes('홍삼') || n.includes('인삼') || n.includes('건강즙') || n.includes('도라지')) {
    return "소중한 분의 건강과 든든한 면역력을 응원하는 마음! 한 포씩 간편하게 챙겨 먹는 정성 가득 프리미엄 건강 기프트 🌿";
  }

  // 12. 한우, 고기, 축산
  if (n.includes('한우') || n.includes('고기') || n.includes('축산') || n.includes('불고기') || n.includes('등심')) {
    return "입안 가득 사르르 녹아내리는 풍부한 육즙과 마블링! 특별한 날 식탁을 최고로 럭셔리하게 빛내줄 감동의 명품 선물 🥩";
  }

  // 13. 과일, 사과, 배, 곶감, 샤인머스캣
  if (n.includes('과일') || n.includes('사과') || n.includes('배') || n.includes('곶감') || n.includes('샤인머스캣')) {
    return "자연 그대로의 달콤함과 아삭한 과즙이 팡팡! 온 가족이 함께 모여 건강하고 맛있게 즐기기 딱 좋은 꿀과일 선물 🍎";
  }

  // 14. 차(Tea), 오설록, 티세트
  if (n.includes('차') || n.includes('오설록') || n.includes('티세트') || n.includes('티 컬렉션')) {
    return "바쁜 일상 속 은은한 향기로 마음을 차분하게 달래주는 여유! 온기와 힐링을 선물하는 감성 티타임 🍵";
  }

  // 15. 텀블러, 보온병, 머그
  if (n.includes('텀블러') || n.includes('보온병') || n.includes('머그')) {
    return "보온·보냉 완벽에 감각적인 디자인까지! 책상 위에 두고 사계절 내내 매일 쓰며 선물한 사람을 기억하게 돼요 ✨";
  }

  // 16. 견과류, 너트
  if (n.includes('견과') || n.includes('너트') || n.includes('아몬드')) {
    return "하루 한 줌으로 챙기는 고소하고 건강한 활력 영양! 일할 때나 쉴 때 부담 없이 챙겨 먹기 최고예요 🥜";
  }

  // 17. 참기름, 들기름, 방앗간
  if (n.includes('참기름') || n.includes('들기름') || n.includes('방앗간')) {
    return "진하고 고소한 향이 입맛을 확 돋우는 전통 방앗간의 깊은 손맛! 식탁의 품격을 높여주는 알짜배기 정성 선물 🍯";
  }

  // 18. 머플러, 장갑, 양말
  if (n.includes('머플러') || n.includes('목도리') || n.includes('장갑') || n.includes('양말')) {
    return "찬 바람 부는 날 포근하게 감싸주는 부드러운 온기! 외출할 때마다 마음까지 훈훈해지는 겨울 필수템 🧣";
  }

  // 19. 브러쉬, 헤어, 아베다
  if (n.includes('브러쉬') || n.includes('빗') || n.includes('아베다')) {
    return "두피를 시원하게 마사지해주며 엉킨 머릿결을 비단처럼 풀어주는 힐링 브러쉬! 매일 아침 기분 좋은 시작 💆‍♀️";
  }

  // 20. 초콜릿, 쿠키, 한과, 베이커리 (경주빵, 찰보리빵 등)
  if (n.includes('초콜릿') || n.includes('쿠키') || n.includes('한과') || n.includes('경주빵') || n.includes('찰보리빵')) {
    return "달콤하고 부드러운 정성 가득 수제 간식! 커피나 차와 곁들이면 순식간에 사라지는 멈출 수 없는 맛 🍪";
  }

  // 21. 세안밴드, 굿즈, 파우치, 담요
  if (n.includes('세안밴드') || n.includes('파우치') || n.includes('담요') || n.includes('가나디')) {
    return "퇴근 후 집에서 쉴 때 볼 때마다 귀여워서 절로 힐링되는 소확행! 실용성과 귀여움을 다 잡은 꿀템 🧸";
  }

  // 22. 수면안대, 베개
  if (n.includes('수면') || n.includes('안대') || n.includes('베개')) {
    return "하루의 피로를 사르르 녹여주는 꿀잠 보장 힐링템! 밤마다 편안하고 포근한 숙면을 선물해 드려요 🌙";
  }

  // 23. 쌀, 혼합미
  if (n.includes('쌀') || n.includes('혼합미') || n.includes('곡물')) {
    return "구수하고 찰진 밥맛으로 든든한 하루를 채워주는 건강 식재료! 밥이 보약이라는 따뜻한 정성을 전해요 🌾";
  }

  // 기존 이유 활용 또는 매력적인 기본 문구
  if (p.reason && !p.reason.includes('가장 반응 좋고') && !p.reason.includes('사회적 가치와')) {
    return p.reason;
  }
  return "선물 받는 순간 환한 미소가 번지는 센스 넘치는 인기 추천 선물이에요 💗";
}

