/* ------------------------------------------------------------
   11. 파티클 폭죽 효과 (Confetti Effect)
   ------------------------------------------------------------ */
function spawnConfetti(index) {
  const panel = document.getElementById(`product-panel-${index}`);
  if (!panel) return;

  const container = document.createElement('div');
  container.className = 'confetti-container';
  panel.style.position = 'relative';
  panel.appendChild(container);

  const colors = ['#FF7597', '#FFB3C6', '#10B981', '#F59E0B', '#A78BFA'];
  for (let i = 0; i < 18; i++) {
    const p = document.createElement('div');
    p.className = 'confetti-dot';
    p.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
    p.style.left = `${45 + (Math.random() * 10 - 5)}%`;
    p.style.top = `${25 + (Math.random() * 10 - 5)}%`;

    const tx = (Math.random() - 0.5) * 160;
    const ty = (Math.random() - 0.7) * 140;
    p.style.setProperty('--tx', `${tx}px`);
    p.style.setProperty('--ty', `${ty}px`);
    p.style.animation = `confettiBurst 0.75s cubic-bezier(0.25, 1, 0.5, 1) forwards`;

    container.appendChild(p);
  }

  setTimeout(() => {
    if (container.parentNode) container.parentNode.removeChild(container);
  }, 850);
}

/* ------------------------------------------------------------
   12. 선물 상자 오픈 전환 애니메이션 오버레이
   ------------------------------------------------------------ */
function triggerGiftBoxOpeningTransition(callback) {
  const overlay = document.getElementById('giftOpeningOverlay');
  if (!overlay) {
    if (callback) callback();
    return;
  }

  overlay.classList.remove('fade-out');
  overlay.classList.add('active');

  setTimeout(() => {
    playSound('celebrate');
  }, 200);

  setTimeout(() => {
    if (callback) {
      try {
        callback();
      } catch (err) {
        console.error('Callback error:', err);
        showView('result');
      }
    }
    overlay.classList.add('fade-out');
    setTimeout(() => {
      overlay.classList.remove('active', 'fade-out');
    }, 300);
  }, 800);
}

/* ------------------------------------------------------------
   13. 다른 선물 추천받기 (리프레시)
   ------------------------------------------------------------ */
window.refreshRecommendations = function() {
  playSound('pop');
  state.recommendationIndex = (state.recommendationIndex + 1) % 5;
  triggerGiftBoxOpeningTransition(() => {
    generateSmartRecommendations();
    showToast("새로운 선물 3가지를 골라왔어! 🎁");
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
};

/* ------------------------------------------------------------
   14. 앱 초기화 및 이벤트 리스너 등록
   ------------------------------------------------------------ */
function initApp() {
  // 사운드 토글 버튼
  const soundBtn = document.getElementById('soundToggleBtn');
  const soundIcon = document.getElementById('soundIcon');
  if (soundBtn) {
    soundBtn.addEventListener('click', () => {
      state.soundEnabled = !state.soundEnabled;
      if (soundIcon) soundIcon.textContent = state.soundEnabled ? '🔔' : '🔕';
      showToast(state.soundEnabled ? "효과음이 켜졌어! 🔔" : "효과음이 꺼졌어 🔕");
    });
  }

  // 로고 클릭 시 첫 화면으로
  const logoBtn = document.getElementById('logoBtn');
  if (logoBtn) {
    logoBtn.addEventListener('click', (e) => {
      e.preventDefault();
      playSound('pop');
      showView('intro');
    });
  }

  // 시작 화면 '선물 골라줘' 버튼
  const startBtn = document.getElementById('startBtn');
  if (startBtn) {
    startBtn.addEventListener('click', () => {
      playSound('pop');
      showView('input');
    });
  }

  // 이전으로 가기 버튼
  const backToIntroBtn = document.getElementById('backToIntroBtn');
  if (backToIntroBtn) {
    backToIntroBtn.addEventListener('click', () => {
      playSound('pop');
      showView('intro');
    });
  }

  // 칩 선택 버튼 그룹 이벤트 바인딩
  const chipButtons = document.querySelectorAll('.select-chip-btn');
  chipButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      playSound('pop');
      const groupEl = btn.closest('[data-group]');
      if (!groupEl) return;
      const group = groupEl.getAttribute('data-group');
      const val = btn.getAttribute('data-value');

      // 같은 그룹 내 active & selected 해제 후 현재 버튼 활성화
      groupEl.querySelectorAll('.select-chip-btn').forEach(b => {
        b.classList.remove('active', 'selected');
      });
      btn.classList.add('active', 'selected');

      state.form[group] = val;

      // 직접입력 박스 처리
      if (group === 'recipient') {
        const box = document.getElementById('recipient-custom-box');
        if (box) {
          box.classList.toggle('show', val === 'custom');
          if (val === 'custom') {
            const input = document.getElementById('recipient-custom-input');
            if (input) input.focus();
          }
        }
      } else if (group === 'situation') {
        const box = document.getElementById('situation-custom-box');
        if (box) {
          box.classList.toggle('show', val === 'custom');
          if (val === 'custom') {
            const input = document.getElementById('situation-custom-input');
            if (input) input.focus();
          }
        }
      } else if (group === 'budget') {
        const customBox = document.getElementById('budget-custom-box');
        if (customBox) {
          customBox.classList.toggle('show', val === 'custom');
        }

        // 예산 버튼 클릭 시 그에 맞게 슬라이더 위치 즉시 이동 (0: 1만원 미만, 1: 1~3만원, 2: 3~5만원, 3: 5~10만원, 4: 10만원 이상)
        const budgetSlider = document.getElementById('budgetRangeSlider') || document.getElementById('budgetSlider');
        const budgetTiers = ['1만원 미만', '1~3만원', '3~5만원', '5~10만원', '10만원 이상'];
        const tierIdx = budgetTiers.indexOf(val);
        if (tierIdx !== -1 && budgetSlider) {
          budgetSlider.value = tierIdx;
        }
      }

      checkFormValidity();
    });
  });

  // 직접입력 인풋 이벤트
  const recipientInput = document.getElementById('recipient-custom-input');
  if (recipientInput) {
    recipientInput.addEventListener('input', (e) => {
      state.form.recipientCustom = e.target.value;
      checkFormValidity();
    });
  }

  const situationInput = document.getElementById('situation-custom-input');
  if (situationInput) {
    situationInput.addEventListener('input', (e) => {
      state.form.situationCustom = e.target.value;
      checkFormValidity();
    });
  }

  // 예산 슬라이더 이벤트 (5개 구간 1:1 눈금 정확한 매칭)
  const budgetSlider = document.getElementById('budgetRangeSlider') || document.getElementById('budgetSlider');
  if (budgetSlider) {
    budgetSlider.addEventListener('input', (e) => {
      const budgetTiers = ['1만원 미만', '1~3만원', '3~5만원', '5~10만원', '10만원 이상'];
      const tierIdx = parseInt(e.target.value, 10);
      const matchedBudget = budgetTiers[tierIdx] || '1~3만원';

      state.form.budget = matchedBudget;
      const budgetGroup = document.querySelector('[data-group="budget"]');
      if (budgetGroup) {
        budgetGroup.querySelectorAll('.select-chip-btn').forEach(b => {
          if (b.getAttribute('data-value') === matchedBudget) {
            b.classList.add('active', 'selected');
          } else {
            b.classList.remove('active', 'selected');
          }
        });
      }

      checkFormValidity();
    });
  }

  const budgetCustomInput = document.getElementById('budget-custom-input');
  if (budgetCustomInput) {
    budgetCustomInput.addEventListener('input', (e) => {
      const val = parseInt(e.target.value, 10);
      if (!isNaN(val) && val > 0) {
        state.form.budgetCustom = val;
        if (budgetValueDisplay) {
          budgetValueDisplay.textContent = `${val.toLocaleString()}원`;
        }
      }
      checkFormValidity();
    });
  }

  // 슬라이더 프리셋 퀵 버튼
  const presetButtons = document.querySelectorAll('.btn-preset-pill');
  presetButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      playSound('pop');
      const amt = parseInt(btn.getAttribute('data-amount'), 10);
      if (budgetSlider) {
        budgetSlider.value = amt;
      }
      state.form.budgetCustom = amt;
      if (budgetValueDisplay) {
        budgetValueDisplay.textContent = `${amt.toLocaleString()}원`;
      }
      checkFormValidity();
    });
  });

  // 제출 버튼 (선물 골라줘 - submitFormBtn 및 submitBtn 호환)
  const submitBtn = document.getElementById('submitFormBtn') || document.getElementById('submitBtn');
  if (submitBtn) {
    submitBtn.addEventListener('click', () => {
      if (!checkFormValidity()) {
        showToast("5가지 조건을 모두 선택해줘! ✍️");
        return;
      }
      playSound('celebrate');
      triggerGiftBoxOpeningTransition(() => {
        showView('result');
        generateSmartRecommendations();
      });
    });
  }

  // 초기 폼 상태 체크
  checkFormValidity();
}
